dcomp calculate_coherent_element(unsigned long n, dcomp alpha) {
    if (n == 0) return 1.0;

    // Calculate the normalization factor e^(-|alpha|^2/2)
    double alpha_norm_sq = std::abs(alpha) * std::abs(alpha);
    dcomp normalization = std::polar(1.0, 0.0); // e^0 = 1
    if (alpha_norm_sq > 1e-15) { // Avoid underflow for very small alpha
        normalization = std::polar(std::exp(-alpha_norm_sq / 2.0), 0.0);
    }

    // For small n, use direct calculation
    if (n < 100) {
        // Calculate alpha^n
        dcomp alpha_power = 1.0;
        for (unsigned long i = 0; i < n; ++i) {
            alpha_power *= alpha;
        }

        // Calculate sqrt(n!)
        double factorial_sqrt = 1.0;
        for (unsigned long i = 1; i <= n; ++i) {
            factorial_sqrt *= i;
        }
        factorial_sqrt = std::sqrt(factorial_sqrt);

        return normalization * alpha_power / factorial_sqrt;
    }

    // For large n, use Stirling approximation: n! ≈ sqrt(2πn) * (n/e)^n
    // So sqrt(n!) ≈ (2πn)^(1/4) * (n/e)^(n/2)
    double log_n_factorial = n * std::log(n) - n + 0.5 * std::log(2 * M_PI * n);
    double sqrt_n_factorial = std::exp(log_n_factorial / 2.0);

    // Calculate alpha^n using polar form for better numerical stability
    double alpha_mag = std::abs(alpha);
    double alpha_phase = std::arg(alpha);
    double alpha_n_mag = std::pow(alpha_mag, n);
    double alpha_n_phase = n * alpha_phase;
    dcomp alpha_n = std::polar(alpha_n_mag, alpha_n_phase);

    return normalization * alpha_n / sqrt_n_factorial;
}

